import itertools

def solve():
    teams = ['Alpha', 'Beta', 'Gamma', 'Delta']
    matches = list(itertools.combinations(teams, 2))
    # Results: 0: Team1 wins, 1: Team2 wins, 2: Draw
    for results in itertools.product([0, 1, 2], repeat=6):
        points = {t: 0 for t in teams}
        match_map = {}
        for i, (t1, t2) in enumerate(matches):
            res = results[i]
            match_map[(t1, t2)] = res
            if res == 0:
                points[t1] += 3
            elif res == 1:
                points[t2] += 3
            else:
                points[t1] += 1
                points[t2] += 1

        if points['Alpha'] == 7 and points['Beta'] == 4 and points['Gamma'] == 3 and points['Delta'] == 1:
            # Found the unique configuration
            # Check if Alpha vs Gamma is a draw (result code 2)
            if match_map[('Alpha', 'Gamma')] == 2:
                return 'C'
    return None

answer = solve()
